  "Лампове радіо": "Tube radio",
  "Ламповий телевізор": "Tube TV",
  "Слухай, у сусідів стільки старої техніки — радіо, телефони… А давай лагодити й збирати! 🛠️ Я облаштував{a} радіомайстерню. Тільки кожну річ треба перевіряти — бо буває й коротке замикання 💥": "Listen, the neighbors have so much old tech — radios, phones… Let's fix it up and build things! 🛠️ I've set up a radio workshop. Just test every piece — short circuits happen 💥",
  "Черепки": "Shards",
  "Скарб": "Treasure",
  "Бурштин із комашкою": "Amber with a bug",
  "ла": "",
  "Нове ремесло: {0}! 🎉": "New craft: {0}! 🎉",
  "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> — уже в майстерні.</p><p class=\"rewards\">{2}</p>": "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> is now in the workshop.</p><p class=\"rewards\">{2}</p>",
  "До роботи! 💪": "Let's get to work! 💪",
  "Горн охолов 🥶 Перетягни на кузню тріску, брусок чи кривий брак із верстака — розпалимо!": "The hearth has cooled 🥶 Drag a wood chip, a block or a wonky reject from the workbench onto the forge — we'll fire it up!",
  "🔥 Кузня холодна — перетягни на неї деревину з верстака": "🔥 The forge is cold — drag wood from the workbench onto it",
  "🐞 Бурштин із комашкою! Рідкісний скарб — за нього дадуть 220 🪙": "🐞 Amber with a bug inside! A rare treasure — it's worth 220 🪙",
  "Жилу вибрали до крихти ⛏️ Нову доведеться покопати — пару годин. Або покличемо копачів, але за гроші.": "We've mined the vein down to the last crumb ⛏️ Digging a new one will take a couple of hours. Or we can hire diggers, but that costs money.",
  "⛏️ Жила вичерпана — копаємо нову": "⛏️ The vein is empty — digging a new one",
  "Жила вичерпана ⛏️": "Vein exhausted ⛏️",
  "<div class=\"big-emoji\">{0}</div><p>Бурштину тут більше нема. Нову жилу відкопаємо за <b>{1}</b>.</p><p class=\"hint-s\">Копачі знайдуть нову одразу.</p>": "<div class=\"big-emoji\">{0}</div><p>There's no amber left here. We'll dig a new vein in <b>{1}</b>.</p><p class=\"hint-s\">Diggers will find a new one right away.</p>",
  "Найняти копачів · {0} 🪙": "Hire diggers · {0} 🪙",
  "⛏️ Нова жила!": "⛏️ New vein!",
  "Почекаю": "I'll wait",
  "🔌 Полагоджено — працює!": "🔌 Fixed — it works!",
  "🔥 У горн — тільки деревину: тріску, брусок, гілочку чи кривий брак": "🔥 Only wood goes in the hearth: a chip, a block, a twig or a wonky reject",
  "🔥 Горн і так розпечений": "🔥 The hearth is already red-hot",
  "Техніку перед тим, як віддати, треба перевірити ❔ Тапни на виріб — і побачимо, чи працює. Якщо замкне 💥 — перетягни на нього дріт, полагодимо.": "Electronics need testing before you hand them over ❔ Tap an item to see if it works. If it shorts out 💥, drag a wire onto it and we'll fix it.",
  "💥 Тріснуло! Лишились черепки…": "💥 It cracked! Only shards left…",
  "Ох, тріснуло 😢 Так буває з глиною — великі речі іноді лускають при злитті. Черепки продай або викинь.": "Oh, it cracked 😢 That happens with clay — big pieces sometimes crack when merged. Sell the shards or throw them away.",
  "Коротке замикання 💥": "Short circuit 💥",
  "<div class=\"big-emoji\">{0}</div><p>«{1}» не працює.</p><p class=\"hint-s\">Перетягни на нього <b>{2} {3}</b> — і полагодиш.</p>": "<div class=\"big-emoji\">{0}</div><p>\"{1}\" doesn't work.</p><p class=\"hint-s\">Drag <b>{2} {3}</b> onto it to fix it.</p>",
  "Перевірити виріб 🧪": "Test the item 🧪",
  "<div class=\"big-emoji\">{0}</div><p>«{1}» — ще не перевірено, тож віддати чи злити поки не можна.</p><p class=\"hint-s\">Буває, що замикає ({2}%) — тоді знадобиться дріт.</p>": "<div class=\"big-emoji\">{0}</div><p>\"{1}\" hasn't been tested yet, so you can't hand it over or merge it.</p><p class=\"hint-s\">Sometimes it shorts out ({2}%) — then you'll need a wire.</p>",
  "🧪 Перевірити · 1 ⚡": "🧪 Test · 1 ⚡",
  "Пізніше": "Later",
  "💥 Замикання! Перетягни на виріб дріт 🔌": "💥 Short circuit! Drag a wire onto the item 🔌",
  "✅ Працює!": "✅ It works!",
