  "Ще трохи — і все буде готово ✨": "Just a little more — and it'll all be ready ✨",
  "{name}, ти справжня майстриня села!": "{name}, you're the village's true master!",
  "Гуртом і батька легше бити, а вже свято готувати — й поготів 😄": "Many hands make light work — and a party even lighter 😄",
  "Ох, як гарно стало! Аж серце радіє 🥹": "Oh, how pretty it's become! My heart is singing 🥹",
  "Бачу, руки в тебе золоті 👐": "I can see you've got hands of gold 👐",
  "Оце по-нашому, по-господарськи! 💪": "Now that's how we do it — proper and thrifty! 💪",
  "Скоро все село збереться — тільки встигай пригощати!": "Soon the whole village will gather — keep the treats coming!",
  "Розбудова села": "Village building",
  "Замовлення сусідів — це зірочки, а зірочки — це наше свято. До роботи!": "Neighbors' orders bring stars, and stars bring our celebration. Let's get to work!",
  "{name}, у селі нова справа — «{0}»! Без тебе не впораємось 💛": "{name}, there's a new project in the village — \"{0}\"! We can't manage without you 💛",
