  "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> — уже на дошці.</p><p class=\"rewards\">{2}</p><p class=\"hint-s\">Тепер сусіди замовлятимуть і {3}.</p>": "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> is already on the board.</p><p class=\"rewards\">{2}</p><p class=\"hint-s\">Now the neighbors will order {3} too.</p>",
