  "<div class=\"big-emoji\">🎁</div><p>Зібрано <b>{0} {1}</b> і отримано {2} з {3} нагород.</p>": "<div class=\"big-emoji\">🎁</div><p>You collected <b>{0} {1}</b> and earned {2} of {3} rewards.</p>",
  "<p class=\"hint-s\">Залишки подарунків ({0} шт.) обміняно на {1} 🪙</p>": "<p class=\"hint-s\">Leftover gifts ({0}) were exchanged for {1} 🪙</p>",
