  "Нагорода свята!": "Festival reward!",
  "<div class=\"big-emoji\">🎁</div><p>Зібрано {0} {1} — тримай:</p><p class=\"rewards\">{2}</p>": "<div class=\"big-emoji\">🎁</div><p>You collected {0} {1} — here you go:</p><p class=\"rewards\">{2}</p>",
  "Дякую! 💛": "Thank you! 💛",
  "Допоможи Ірині й Марічці зібрати подарунки для сільських дітей! Тапай скриньку, об'єднуй подарунки й віддавай їм.": "Help Ms. Iryna and Marichka gather gifts for the village kids! Tap the box, merge the gifts and hand them out.",
  "· до наступної нагороди ще {0} {1}": "· {0} {1} to the next reward",
  "· усі нагороди зібрано! 🎉": "· all rewards collected! 🎉",
  "<p>{0}</p> <p class=\"ev-sum\"><b>{1} {2}</b>{3}<br><small>До кінця свята: {4}</small></p> <div class=\"ev-list\">{5}</div>": "<p>{0}</p> <p class=\"ev-sum\"><b>{1} {2}</b>{3}<br><small>Festival ends in: {4}</small></p> <div class=\"ev-list\">{5}</div>",
  "Зрозуміло": "Got it",
  "📜 Історія свята": "📜 Festival story",
  "я вам пелюшок нашила — вишиваних, як годиться 🧵 І ось вам енергії, бережіть себе!": "I've sewn you some baby wraps — embroidered, just as it should be 🧵 And here's some energy for you, take care of yourselves!",
  "принесла дитячих книжечок і пиріжків — їжте, вам тепер за двох 😄": "I brought some children's books and pyrizhky — eat up, you're eating for two now 😄",
  "сплела маленький віночок-оберіг на колиску 🌼": "I wove a tiny protective vinok for the cradle 🌼",
  "колиску вже пробували гойдати? Ото ж! А це від нас із бабою — на дитячу 🪵": "tried rocking the cradle yet? There you go! And this is from Granny and me — for the nursery 🪵",
  "букет нареченої": "bride's bouquet",
  "весільний торт": "wedding cake",
