  "<button class=\"s-btn dc-put\" data-e=\"{0}\">Поставити</button>": "<button class=\"s-btn dc-put\" data-e=\"{0}\">Place</button>",
  "Купити": "Buy",
  "<button class=\"dc-placed\" data-id=\"{0}\" title=\"Прибрати\">{1}<i>✕</i></button>": "<button class=\"dc-placed\" data-id=\"{0}\" title=\"Remove\">{1}<i>✕</i></button>",
  "Двір на свій смак 🎨": "Your yard, your way 🎨",
  "<p class=\"hint-s\">Купи прикрасу, натисни «Поставити» — і тапни на землю у дворику.</p>": "<p class=\"hint-s\">Buy a decoration, tap \"Place\" — then tap the ground in the yard.</p>",
  "<div class=\"dc-here\"><small>Уже стоїть тут (тапни, щоб прибрати назад у скриньку):</small><div>{0}</div></div>": "<div class=\"dc-here\"><small>Already placed here (tap to put it back in the box):</small><div>{0}</div></div>",
  "Готово 💛": "Done 💛",
  "Розставляти можна у 3D-дворику": "Decorations can be placed in the 3D yard",
  "{0} Тапни на землю у дворику, куди поставити": "{0} Tap the ground in the yard where it should go",
  "Тапни на саму землю дворика 🌱": "Tap right on the yard's ground 🌱",
  "{0} Гарно стало!": "{0} Looks lovely!",
  "розставлено прикрас: {0}": "decorations placed: {0}",
  "купуй прикраси й став де хочеш": "buy decorations and place them anywhere",
  "Почім оце? Гарна робота!": "How much for this? Fine work!",
  "Мені б таке — на подарунок 🎁": "Just the thing for a gift 🎁",
  "Ой, яке! Беру, якщо не дорого.": "Oh, how lovely! I'll take it if it's not too pricey.",
  "Давно таке шукаю!": "I've been looking for one of these!",
  "Ярмарок вихідного дня 🎪": "Weekend fair 🎪",
  "<div class=\"big-emoji\">🎪</div><p>Ярмарок буває по суботах і неділях. Готуй вироби в майстерні — покупці торгуються, але платять щедріше, ніж сусіди!</p>": "<div class=\"big-emoji\">🎪</div><p>The fair runs on Saturdays and Sundays. Make crafts in the workshop — buyers haggle, but they pay more than the neighbors do!</p>",
  "Чекатиму 💛": "Can't wait 💛",
  "<small class=\"fr-ok\">продано ✅</small>": "<small class=\"fr-ok\">sold ✅</small>",
  "<small class=\"fr-gone\">пішов до іншого 🚶</small>": "<small class=\"fr-gone\">went elsewhere 🚶</small>",
  "<button class=\"s-btn fr-sell{0}\" data-k=\"{1}\">Продати · {2} 🪙</button>": "<button class=\"s-btn fr-sell{0}\" data-k=\"{1}\">Sell · {2} 🪙</button>",
  "<button class=\"s-btn ghost fr-hag\" data-k=\"{0}\">Торгуватися</button>": "<button class=\"s-btn ghost fr-hag\" data-k=\"{0}\">Haggle</button>",
  "· немає в майстерні": "· none in the workshop",
  "<div class=\"fr-row{0}\">{1}<span class=\"fr-t\"><b>{2}</b><small>хоче {3} {4}{5}</small></span><span class=\"fr-b\">{6}</span></div>": "<div class=\"fr-row{0}\">{1}<span class=\"fr-t\"><b>{2}</b><small>wants {3} {4}{5}</small></span><span class=\"fr-b\">{6}</span></div>",
  "<p class=\"hint-s\">Покупці беруть вироби з майстерні. Торгуйся — можна виторгувати більше, але покупець може й піти!</p><div class=\"fr-list\">{0}</div>": "<p class=\"hint-s\">Buyers want crafts from the workshop. Haggle — you might get more, but the buyer might walk away!</p><div class=\"fr-list\">{0}</div>",
  "Зроби в майстерні {0} {1}": "Make {0} {1} in the workshop",
  "🎪 {0}: «Дякую! Хай служить довго!» +{1} 🪙": "🎪 {0}: \"Thank you! May it serve me well!\" +{1} 🪙",
  "🤝 {0}: «Ну добре, {1} — і по руках!»": "🤝 {0}: \"Oh, all right, {1} — it's a deal!\"",
  "😤 {0}: «Ну й дорого! Піду до іншого майстра.»": "😤 {0}: \"Way too pricey! I'll go to another craftsman.\"",
  "Ярмарок вихідного дня": "Weekend fair",
  "найближчий — у суботу (через {0} дн.)": "next one on Saturday (in {0} d)",
  "{0} покупці чекають на вироби з майстерні": "{0} buyers waiting for workshop crafts",
  "усіх покупців обслужено 💛": "all buyers served 💛",
  "По суботах і неділях приходять 4 покупці й просять вироби з майстерні — платять у півтора раза більше. Можна торгуватися: першого разу вдається частіше, а другого — ризик, що покупець піде.": "Every Saturday and Sunday, 4 buyers come asking for workshop crafts — and pay one and a half times more. You can haggle: the first try works more often, but a second one risks the buyer walking away.",
  "Святковий віночок": "Holiday vinok",
  "Віночок зі стрічками": "Vinok with ribbons",
