  "{0} {1} — у «Двір на свій смак» 🎨": "{0} {1} — added to \"Your yard, your way\" 🎨",
  "Кому подарувати? 💝": "Who gets it? 💝",
  "<p>Хто сьогодні отримає {0}?</p>": "<p>Who gets the {0} today?</p>",
  "Краще в дворик": "Into the yard instead",
  "Ой, яка краса! Сама б так не змогла 🥹 Дякую від щирого серця!": "Oh, how lovely! I could never make that myself 🥹 Thank you from the bottom of my heart!",
  "Ой, яка краса! Сам би так не зміг 🥹 Дякую від щирого серця!": "Oh, how lovely! I could never make that myself 🥹 Thank you from the bottom of my heart!",
  "Це ж справжній оберіг! Повішу на найпочесніше місце 💛": "Why, it's a real good-luck charm! I'll hang it in the place of honor 💛",
  "Ну й руки в тебе, {name}! Тримай гостинця — від мене 🍯": "What golden hands you have, {name}! Here's a little treat from me 🍯",
  "💛 {0}: дружба +1 · +{1} 🪙": "💛 {0}: friendship +1 · +{1} 🪙",
