  "Рівень": "Level",
  "<div class=\"big-emoji\">🌟</div><p>Ти молодчинка! Тримай подарунки:</p><p class=\"rewards\">+{0} ⚡ &nbsp; {1}</p>": "<div class=\"big-emoji\">🌟</div><p>Well done, you! Here are some gifts:</p><p class=\"rewards\">+{0} ⚡ &nbsp; {1}</p>",
  "🥀 Частина продуктів зачерствіла — −{0} 🪙": "🥀 Some of the food went stale — −{0} 🪙",
