  "⭐ — виконуй замовлення сусідів": "more ⭐ — fill your neighbors' orders",
  "Розділ завершено! 🎉": "Chapter complete! 🎉",
  "<p class=\"chapter-done\">«{0}»</p><p>Нагорода чекає на дошці:</p><p class=\"rewards\">{1}</p>": "<p class=\"chapter-done\">\"{0}\"</p><p>Your reward is waiting on the board:</p><p class=\"rewards\">{1}</p>",
  "<p class=\"hint-s\">Новий генератор! Тепер сусіди замовлятимуть і {0}.</p>": "<p class=\"hint-s\">A new producer! Now neighbors will order {0} too.</p>",
  "<p class=\"hint-s\">🎨 Сувенір розділу — у «Двір на свій смак» (кнопка 🎨 у «Дворику»).</p>": "<p class=\"hint-s\">🎨 The chapter souvenir goes to \"Your yard, your way\" (the 🎨 button in the \"Yard\").</p>",
  "<p class=\"hint-s\">📷 Дворик сфотографовано — знімок у фотоальбомі (профіль).</p>": "<p class=\"hint-s\">📷 The yard got its picture taken — the photo is in your album (profile).</p>",
  "Це ще не кінець, {name}! Нові розділи вже пишуться 💌 А поки — сусіди чекають на замовлення!": "This isn't the end, {name}! New chapters are being written 💌 Meanwhile, the neighbors are waiting for their orders!",
  "Щоденний подарунок 🎁": "Daily gift 🎁",
  "Кожен третій день — велика посилка!": "Every third day — a big parcel!",
  "<div class=\"big-emoji\">{0}</div><p>День {1} поспіль! {2}</p><p class=\"rewards\">+{3} ⚡ &nbsp; {4}</p>": "<div class=\"big-emoji\">{0}</div><p>Day {1} in a row! {2}</p><p class=\"rewards\">+{3} ⚡ &nbsp; {4}</p>",
