  "<br>Енергію на сьогодні вже купувала — завтра крамничка знову відкриється.": "<br>You've already bought energy today — the shop opens again tomorrow.",
  "<div class=\"big-emoji\">🫖</div> <p>Город відпочиває. Наступна ⚡ буде за <b id=\"neNext\">{0}</b>,<br>повна шкала ({1} ⚡) — за <b id=\"neFull\">{2}</b>.</p> <p class=\"hint-s\">Поки чекаєш — об'єднуй те, що вже є на дошці, і виконуй замовлення.{3}</p>": "<div class=\"big-emoji\">🫖</div> <p>The garden is resting. Next ⚡ in <b id=\"neNext\">{0}</b>,<br>full bar ({1} ⚡) in <b id=\"neFull\">{2}</b>.</p> <p class=\"hint-s\">While you wait, merge what's already on the board and fill orders.{3}</p>",
