  "<p>Це твій код прогресу (рівень {0}, розділ {1}). Збережи його в Нотатки або надішли собі в месенджер.</p> <textarea class=\"backup-code\" id=\"bkCode\" readonly>{2}</textarea>": "<p>This is your progress code (level {0}, chapter {1}). Save it in Notes or send it to yourself in a messenger.</p> <textarea class=\"backup-code\" id=\"bkCode\" readonly>{2}</textarea>",
