  "хіт": "popular",
  "хв без меж": "min unlimited",
  "хв гри": "min of play",
  "Скоро 💎": "Coming soon 💎",
  "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> — {2}</p><p>Справжні покупки ще не підключені, тож гроші ніде не списуються 🙂</p><p class=\"hint-s\">Поки що все в грі — за монетки 🪙, зірочки ⭐ і терпіння ☕</p>": "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> — {2}</p><p>Real purchases aren't connected yet, so no money is charged 🙂</p><p class=\"hint-s\">For now, everything in the game costs coins 🪙, stars ⭐ and patience ☕</p>",
  "Тестова покупка": "Test purchase",
  "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> ({2}) — у тестовому режимі видається без оплати.</p>": "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> ({2}) — free in test mode.</p>",
  "Отримати": "Get it",
