  "{name}, {0}? У село {1} з дерева! {2} стару хату біля млина.": "{name}, {0}? {1} who works with wood has moved to the village! {2} the old house by the mill.",
  "Добридень! Я {0}. Різьблю з дерева — ложки, скриньки, колиски… Тільки ще нікого тут не знаю 😅": "Hello! I'm {0}. I carve wood — spoons, boxes, cradles… But I don't know anyone here yet 😅",
  "Допоможеш мені облаштуватися? Я поки буду в тебе дещо замовляти — а потім віддячу 💛": "Will you help me settle in? I'll order a few things from you for now — and I'll pay you back later 💛",
  "💕 Віддай {0} 3 замовлення": "💕 Complete 3 orders for {0}",
  "допоміг": "helped",
  "допомогла": "helped",
  "{name}, ти так мені {0}… Ходімо ввечері до річки? Там такий захід сонця 🌅": "{name}, you've {0} me so much… Shall we go down to the river this evening? The sunset there is beautiful 🌅",
  "Ой, та це ж побачення! 😍 Тільки з порожніми руками не йди — подаруй святковий букет 💐": "Oh, that's a date! 😍 Just don't go empty-handed — bring a festive bouquet 💐",
  "💐 Принеси святковий букет — і йди на побачення (у «Подіях»)": "💐 Bring a festive bouquet — and go on the date (in \"Events\")",
  "Спершу збери {0} {1}": "First collect {0} {1}",
  "Це мені? 🥹 Найгарніший букет у моєму житті…": "Is this for me? 🥹 The most beautiful bouquet of my life…",
  "хотів": "wanted",
  "хотіла": "wanted",
  "Знаєш… я давно {0} сказати — з тобою мені тут, як удома 💛": "You know… I've long {0} to tell you — with you, this place feels like home 💛",
  "Ой, дивіться-но, голубки над річкою 😊 Будуть люди!": "Oh, look at those two lovebirds by the river 😊 They'll make a fine pair!",
  "💕 Віддай {0} ще 5 замовлень": "💕 Complete 5 more orders for {0}",
  "думав": "been thinking",
  "думала": "been thinking",
  "відремонтував": "fixed up",
  "відремонтувала": "fixed up",
  "{name}, я довго {0}… Хату біля млина я вже майже {1}. Тільки без тебе вона порожня.": "{name}, I've {0} for a long time… I've almost {1} the house by the mill. But without you it feels empty.",
  "переробив": "turned",
  "переробила": "turned",
  "Будемо жити разом? 💍 А стару повітку я {0} на майстерню — для нас обох!": "Shall we live together? 💍 And I've {0} the old shed into a workshop — for both of us!",
  "Будемо жити разом? 💕": "Shall we live together? 💕",
  "<div class=\"big-emoji\">💕</div><p>{0} кличе тебе жити разом.</p><p class=\"hint-s\">Відкриється спільна майстерня з дерева — окрема дошка з виробами, своїми замовленнями й розширенням.</p>": "<div class=\"big-emoji\">💕</div><p>{0} asks you to move in together.</p><p class=\"hint-s\">This opens a shared wood workshop — a separate board with crafts, its own orders and upgrades.</p>",
  "Так! 💍": "Yes! 💍",
  "Ох, яке щастя! 🥹 Ми з дідом Степаном теж колись отак починали…": "Oh, such happiness! 🥹 Grandpa Stepan and I started out just like that…",
  "Майстерня — це добре! Руки при ділі — і в хаті лад 🪚": "A workshop is a good thing! Busy hands make a tidy home 🪚",
  "Ходімо, покажу майстерню! Кнопка 🪚 під дошкою. Там свої замовлення — сусіди вже чекають на ложки й скриньки 😊": "Come on, I'll show you the workshop! The 🪚 button is under the board. It has its own orders — the neighbors are already waiting for spoons and boxes 😊",
  "знайомство: замовлення {0}/3": "getting to know: orders {0}/3",
  "побачення: подаруй {0} святковий букет": "date: give a festive bouquet {0}",
  "ближче: замовлення {0}/5": "getting closer: orders {0}/5",
  "живете разом 💕 · майстерня 🪚": "living together 💕 · workshop 🪚",
  "Подарувати 💐": "Give 💐",
  "Спершу повернись із пригоди 🙂": "Come back from your adventure first 🙂",
  "Ось наша майстерня! 🪚 Тапай верстак — буде тріска, з тріски брусок, а там і до шафи недалеко 😄 Енергія та сама, що й на городі.": "Here's our workshop! 🪚 Tap the workbench — you'll get wood chips, chips make a block, and from there it's not far to a wardrobe 😄 Same energy as in the garden.",
  "<span class=\"sd-ic\">🪴</span><small>Город</small>": "<span class=\"sd-ic\">🪴</span><small>Garden</small>",
  "<span class=\"sd-ic\">🪚</span><small>Майстерня</small>": "<span class=\"sd-ic\">🪚</span><small>Workshop</small>",
  "поставив": "set up",
  "поставила": "set up",
  "Ти так гарно працюєш! Я {0} тобі різьбярський стіл 🪓 — тепер і коників, і скрипки робитимемо!": "You work so beautifully! I've {0} a carving table for you 🪓 — now we can make little horses and even violins!",
  "виробів віддано: {0} · дошка {1}/4{2}": "crafts delivered: {0} · board {1}/4{2}",
  "знову працює!": "is working again!",
  "Відпочиває 💤": "Resting 💤",
  "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> відпочиває ще <b>{2}</b> і знову буде повний сил.</p> <p class=\"hint-s\">Поки що потапай інші генератори або об'єднай те, що вже є. Два однакові генератори зливаються в кращий — з більшим зарядом.</p>": "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> is resting for another <b>{2}</b> and will be back at full strength.</p> <p class=\"hint-s\">Meanwhile, tap other producers or merge what you already have. Two identical producers merge into a better one — with a bigger charge.</p>",
  "Розбудити за {0} 🪙": "Wake up for {0} 🪙",
  "Хай відпочине": "Let it rest",
  "Кращий генератор! ⭐": "Better producer! ⭐",
  "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> тепер рівня {2}!</p> <p class=\"rewards\">{3} ⚡ заряду · відпочинок {4} хв</p><p class=\"hint-s\">І частіше дає одразу кращі предмети.</p>": "<div class=\"big-emoji\">{0}</div><p><b>{1}</b> is now level {2}!</p> <p class=\"rewards\">{3} ⚡ charge · rest {4} min</p><p class=\"hint-s\">It also gives better items right away more often.</p>",
  "Ще один {0} {1}! Об'єднай два однакові — буде кращий": "Another {0} {1}! Merge two identical ones — you'll get a better one",
  "Павутиння 🕸️": "Cobweb 🕸️",
  "(ще {0} рази)": "({0} more times)",
  "<div class=\"big-emoji\">🕸️</div><p>Під павутинням щось є! Об'єднай предмети на сусідній клітинці — і воно зникне{0}.</p>": "<div class=\"big-emoji\">🕸️</div><p>There's something under the cobweb! Merge items on a neighboring cell — and it will disappear{0}.</p>",
  "Розчистити за {0} 🪙": "Clear for {0} 🪙",
