  "Піч 🔥": "Oven 🔥",
  "<div class=\"big-emoji\">{0}</div><p>Готується <b>{1}</b> — ще <b>{2}</b>.</p>": "<div class=\"big-emoji\">{0}</div><p>Cooking <b>{1}</b> — <b>{2}</b> left.</p>",
  "Пришвидшити за {0} 🪙": "Speed up for {0} 🪙",
  "Зачекаю": "I'll wait",
  "<div class=\"rc-row\"><span class=\"rc-out\">{0}</span><span class=\"rc-mid\"><b>{1}</b><span class=\"rc-need\">{2} · ⏱ {3} хв</span></span>": "<div class=\"rc-row\"><span class=\"rc-out\">{0}</span><span class=\"rc-mid\"><b>{1}</b><span class=\"rc-need\">{2} · ⏱ {3} min</span></span>",
  "Готувати": "Cook",
  "Бракує": "Missing",
  "<p class=\"hint-s\">Рецепти відкриються, коли з'являться нові генератори.</p>": "<p class=\"hint-s\">Recipes unlock when new producers appear.</p>",
  "<p class=\"hint-s\">Поклади два інгредієнти — і за кілька хвилин буде страва. Страви просять сусіди за ⭐⭐ і багато монеток.</p><div class=\"rc-list\">{0}</div>": "<p class=\"hint-s\">Put in two ingredients — and in a few minutes you'll have a dish. Neighbors ask for dishes and pay ⭐⭐ and lots of coins.</p><div class=\"rc-list\">{0}</div>",
  "Бракує інгредієнтів — назбирай на дошці": "Missing ingredients — gather them on the board",
  "готується": "cooking",
  "поїхав далі — скарбу так і не дочекався 🧐": "moved on — never got the treasure 🧐",
  "вже не чекає — термінове замовлення минуло ⏰": "isn't waiting anymore — the urgent order expired ⏰",
  "{name}, я полагодив стару піч! 🔥 Тепер можна готувати справжні страви.": "{name}, I fixed the old oven! 🔥 Now you can cook real dishes.",
  "Тапни піч — там рецепти. Борщ, вареники з вишнями… Клади інгредієнти й чекай, поки зготується.": "Tap the oven — the recipes are in there. Borscht, varenyky with cherries… Add the ingredients and wait till it's cooked.",
  "Ох, і замовлятиму ж я в тебе вареники! За страви плататимемо щедро — і зірочками теж ⭐⭐": "Oh, I'll be ordering varenyky from you all the time! We'll pay well for dishes — in stars too ⭐⭐",
