  "<p class=\"hint-s\">За кожну справу в грі — медалі трьох ступенів: 🥉 → 🥈 → 🥇. Що вища медаль, то щедріша нагорода.</p><div class=\"md-list\">{0}</div>": "<p class=\"hint-s\">Every activity in the game has medals of three tiers: 🥉 → 🥈 → 🥇. The higher the medal, the bigger the reward.</p><div class=\"md-list\">{0}</div>",
