  "<div class=\"big-emoji\">{0}</div><p>«{1}» тепер прикрашає твій дворик 🏡</p><p class=\"rewards\">💝 &nbsp; +{2} 🪙</p><p class=\"hint-s\">А кроки й далі приносять подарунки 🎁 — кожні {3}.</p>": "<div class=\"big-emoji\">{0}</div><p>\"{1}\" now decorates your yard 🏡</p><p class=\"rewards\">💝 &nbsp; +{2} 🪙</p><p class=\"hint-s\">And your steps keep bringing gifts 🎁 — every {3} steps.</p>",
