  "(уже {0})": "(already {0})",
  "<div class=\"ph-row inf{0}\"><span class=\"ph-n\">∞</span><span class=\"ph-ic\">🎁</span><span class=\"ph-t\">Після 30-го — подарунок кожні {1} кроків{2}</span>": "<div class=\"ph-row inf{0}\"><span class=\"ph-n\">∞</span><span class=\"ph-ic\">🎁</span><span class=\"ph-t\">After level 30 — a gift every {1} steps{2}</span>",
