  "<p class=\"dq-hint\">Кроки: замовлення +{0} (особливі +{1}) · завдання дня +{2} · тиждень +{3} · пригода +{4}</p>": "<p class=\"dq-hint\">Steps: order +{0} (special +{1}) · daily tasks +{2} · week +{3} · adventure +{4}</p>",
  "<button class=\"btn dq-claim ph-all\">Забрати все 🎁</button>": "<button class=\"btn dq-claim ph-all\">Claim all 🎁</button>",
  "<p class=\"dq-hint\">Головна нагорода — {0} «{1}» у твій дворик. Щомісяця — нова стежка.</p>": "<p class=\"dq-hint\">Grand prize: {0} \"{1}\" for your yard. A new path every month.</p>",
  "завершилась": "has ended",
  "<div class=\"big-emoji\">{0}</div><p>Незабрані нагороди вже чекають на тебе:</p><p class=\"rewards\">{1}</p><p class=\"hint-s\">Починається «{2}» {3}</p>": "<div class=\"big-emoji\">{0}</div><p>Your unclaimed rewards are waiting for you:</p><p class=\"rewards\">{1}</p><p class=\"hint-s\">Now starting: \"{2}\" {3}</p>",
  "До нової стежки ›": "To the new path ›",
  "📷 Знімок дворика — у фотоальбомі (профіль)": "📷 Yard snapshot saved to the photo album (profile)",
  "📸 Клац! Фото — у фотоальбомі": "📸 Click! Photo saved to the album",
  "На цьому телефоні дворик без 3D — фото не вийде 🙈": "The yard has no 3D on this phone — can't take a photo 🙈",
  "<div>📸 Фотографую дворик…<br><b>{0} з {1}</b><small>{2}</small></div>": "<div>📸 Photographing the yard…<br><b>{0} of {1}</b><small>{2}</small></div>",
  "📷 Готово! У фотоальбомі {0} нових знімків": "📷 Done! {0} new photos in the album",
  "Фотоальбом 📷 {0}": "Photo album 📷 {0}",
  "<button class=\"btn small ph-back\" id=\"phBack\">📸 Сфотографувати пройдені розділи ({0})</button>": "<button class=\"btn small ph-back\" id=\"phBack\">📸 Photograph completed chapters ({0})</button>",
  "<div class=\"big-emoji\">📷</div><p>Альбом поки порожній. Після кожного розділу дворик фотографується сам, а ще є кнопка 📸 у дворику.</p>": "<div class=\"big-emoji\">📷</div><p>The album is empty for now. After each chapter, the yard takes its own photo — and there's also a 📸 button in the yard.</p>",
  "<p class=\"hint-s\">Фото зберігаються лише на цьому телефоні — у код резервної копії вони не входять. Щоб зберегти назавжди, відкрий фото й натисни «Поділитися» → «Зберегти зображення».</p>": "<p class=\"hint-s\">Photos are stored only on this phone — they aren't included in the backup code. To keep one forever, open it and tap \"Share\" → \"Save Image\".</p>",
  "Мій дворик": "My yard",
  "📤 Поділитися / зберегти": "📤 Share / save",
  "🗑 Видалити": "🗑 Delete",
  "До альбому": "Back to album",
  "Затишний дворик": "Cozy Yard",
  "Хочу справжнього домашнього сиру — у місті такого не знайдеш!": "I'd love real homemade cheese — you can't find that in the city!",
  "Діти просять сільського молочка — пришліть, будь ласка!": "The kids are asking for village milk — please send some!",
  "Шукаю козячий сир від господині, а не з магазину": "Looking for goat cheese from a real farm, not a store",
  "В'яжу светри — потрібна добра овеча вовна": "I knit sweaters — I need good sheep's wool",
