  "Житомир": "Zhytomyr",
  "Усе дійшло ціле, дякую! Найкраща господиня в країні ⭐⭐⭐⭐⭐": "Everything arrived in one piece, thank you! The best homesteader in the country ⭐⭐⭐⭐⭐",
  "Розпакували всією родиною — у захваті! Замовлю ще 💛": "The whole family unpacked it together — we love it! Will order again 💛",
  "Якість — неймовірна. Порадила всім подругам!": "The quality is incredible. I've recommended you to all my friends!",
  "Дуже швидко й з любов'ю запаковано. Дякую! ⭐⭐⭐⭐⭐": "Super fast and packed with love. Thank you! ⭐⭐⭐⭐⭐",
  "Саме те, що треба було! Щиро дякую 🙏": "Just what I needed! Thank you so much 🙏",
  "Посилки поштою": "Parcel post",
  "Люди з інших міст замовляють твої вироби: домашній сир і молочне, дерев'яні й ковані речі, кераміку, бурштин, електроніку. Збери замовлене й відправ через листоношу Івана — оплата прийде, щойно посилка доїде. Шукай у «Подіях».": "People from other cities order your goods: homemade cheese and dairy, wooden and wrought-iron pieces, pottery, amber, electronics. Gather the order and send it with Ivan the mailman — payment arrives as soon as the parcel does. Look in \"Events\".",
  "{name}, мені тепер з усієї країни листи йдуть — і всі про тебе! 📮 Хочуть твоїх виробів. Збирай — а я відправлю посилкою": "{name}, I'm getting letters from all over the country now — and they're all about you! 📮 They want your goods. Gather them — and I'll send them by parcel",
  "У «Подіях» — замовлення з інших міст (сир і молочне, дерев'яні, ковані, гончарні вироби, бурштин, електроніка — з того, що в тебе вже є). Знайди вироби на городі чи в майстерні й тисни «Відправити». Посилка їде кілька годин, тоді приходить оплата й відгук. Більше відгуків — щедріша оплата.": "In \"Events\" you'll find orders from other cities (cheese and dairy, wooden, wrought-iron and pottery goods, amber, electronics — from what you already have). Find the goods in the garden or the workshop and tap \"Send\". A parcel takes a few hours, then the payment and a review arrive. More reviews — better pay.",
  "📦 Посилку для {0} ({1}) відправлено! Оплата — щойно доїде": "📦 Parcel for {0} ({1}) sent! Payment comes when it arrives",
  "Посилка дійшла! {0} з міста {1} пише: «{2}» 📮 Оплата вже у тебе: +{3} 🪙 +{4} ⭐": "The parcel arrived! {0} from {1} writes: \"{2}\" 📮 Payment is already yours: +{3} 🪙 +{4} ⭐",
  "не дочекалась і скасувала": "got tired of waiting and canceled",
  "не дочекався й скасував": "got tired of waiting and canceled",
  "📮 {0} ({1}) {2} замовлення": "📮 {0} ({1}) {2} the order",
  "📮 Нове замовлення поштою: {0} ({1}) — {2}": "📮 New mail order: {0} ({1}) — {2}",
  "<button class=\"s-btn post-send{0}\" data-id=\"{1}\">Відправити</button></div>": "<button class=\"s-btn post-send{0}\" data-id=\"{1}\">Send</button></div>",
  "<div class=\"wd-row\"><span class=\"wd-ava\">🚚</span><span class=\"wd-mid\"><b>{0} · {1}</b><small>у дорозі ще {2} · оплата +{3} 🪙</small></span></div>": "<div class=\"wd-row\"><span class=\"wd-ava\">🚚</span><span class=\"wd-mid\"><b>{0} · {1}</b><small>on the way for {2} more · payment +{3} 🪙</small></span></div>",
  "Посилки поштою 📮": "Parcel post 📮",
  "<p class=\"hint-s\">Замовляють домашній сир і молочне, дерев'яні, ковані, гончарні вироби, бурштин і електроніку. Щойно в тебе з'явиться курник, хлів чи майстерня — підуть і замовлення.</p>": "<p class=\"hint-s\">People order homemade cheese and dairy, wooden, wrought-iron and pottery goods, amber and electronics. As soon as you have a henhouse, barn or workshop, the orders will start coming.</p>",
  "<p>Поки нових замовлень немає — наступне прийде за <b>{0}</b>.</p>": "<p>No new orders yet — the next one arrives in <b>{0}</b>.</p>",
  "<p class=\"dq-when\">У дорозі</p><div class=\"wd-list\">{0}</div>": "<p class=\"dq-when\">On the way</p><div class=\"wd-list\">{0}</div>",
  "· за них платять щедріше: +{0}%": "· they boost your pay: +{0}%",
