  "Весна": "Spring",
  "Писанки": "Pysanky",
  "Писанка-заготовка": "Blank pysanka",
  "Гніздо писанок": "Nest of pysanky",
  "Писанка-оберіг": "Pysanka charm",
  "Літо": "Summer",
  "Липовий мед": "Linden honey",
  "Медовий соняшник": "Honey sunflower",
  "Воскова свічка": "Beeswax candle",
  "Глечик липового меду": "Jug of linden honey",
  "Осінь": "Autumn",
